-- Allow a user to insert their own profile row (fallback / belt-and-suspenders)
drop policy if exists "Users can insert their own profile" on public.profiles;
create policy "Users can insert their own profile"
  on public.profiles for insert
  with check (auth.uid() = id);

-- Auto-create a profile whenever an auth user is created.
-- Runs as SECURITY DEFINER so it bypasses RLS, and never blocks signup on error.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name   text;
  v_handle text;
begin
  v_name   := coalesce(nullif(new.raw_user_meta_data->>'name', ''),
                        split_part(new.email, '@', 1));
  v_handle := coalesce(nullif(new.raw_user_meta_data->>'handle', ''),
                        split_part(new.email, '@', 1));
  -- strip a leading @ if the user typed one
  v_handle := ltrim(v_handle, '@');

  -- guarantee handle uniqueness
  if exists (select 1 from public.profiles p where p.handle = v_handle) then
    v_handle := v_handle || '-' || substr(replace(new.id::text, '-', ''), 1, 4);
  end if;

  begin
    insert into public.profiles (id, name, handle)
    values (new.id, v_name, v_handle)
    on conflict (id) do nothing;
  exception when others then
    -- never let profile creation block account creation
    null;
  end;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

