'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import { useAuth } from '@/lib/useAuth'

type Author = { name: string; handle: string }

type Post = {
  id: string
  activity: string
  location: string
  starts_at: string
  duration_min: number
  price: number | null
  cap: number | null
  author: Author | Author[] | null
  author_id: string
  status: string
}

const ACTIVITY_EMOJI: Record<string, string> = {
  Badminton: '🏸',
  Pickleball: '🏓',
  Padel: '🎾',
  Run: '🏃',
  Gym: '🏋️',
}

function authorOf(post: Post): Author | null {
  return Array.isArray(post.author) ? post.author[0] ?? null : post.author
}

export default function Home() {
  const router = useRouter()
  const { user, loading: authLoading } = useAuth()
  const [posts, setPosts] = useState<Post[]>([])
  const [loading, setLoading] = useState(true)
  const [joined, setJoined] = useState<Set<string>>(new Set())
  const [joining, setJoining] = useState<string | null>(null)
  const [greeting, setGreeting] = useState<string>('')

  useEffect(() => {
    if (authLoading) return

    if (!user) {
      router.push('/signup')
      return
    }

    fetchProfile()
    fetchPosts()
    fetchJoined()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, authLoading])

  async function fetchProfile() {
    if (!user) return
    const { data } = await supabase
      .from('profiles')
      .select('name, handle')
      .eq('id', user.id)
      .single()
    setGreeting(data?.name?.split(' ')[0] || data?.handle || user.email?.split('@')[0] || '')
  }

  async function fetchPosts() {
    setLoading(true)
    const { data, error } = await supabase
      .from('posts')
      .select(
        `id, activity, location, starts_at, duration_min, price, cap, author_id, status, author:profiles(name, handle)`,
      )
      .eq('status', 'upcoming')
      .order('starts_at', { ascending: true })

    if (error) {
      console.error('Error fetching posts:', error)
      setLoading(false)
      return
    }

    setPosts((data as unknown as Post[]) || [])
    setLoading(false)
  }

  async function fetchJoined() {
    if (!user) return
    const { data } = await supabase
      .from('joins')
      .select('post_id')
      .eq('user_id', user.id)

    if (data) setJoined(new Set(data.map((j) => j.post_id)))
  }

  async function joinActivity(postId: string) {
    if (!user || joined.has(postId)) return
    setJoining(postId)
    const { error } = await supabase
      .from('joins')
      .insert({ post_id: postId, user_id: user.id })

    // A unique-violation just means they already joined — treat as success.
    if (!error || error.code === '23505') {
      setJoined((prev) => new Set([...prev, postId]))
    }
    setJoining(null)
  }

  async function handleLogout() {
    await supabase.auth.signOut()
    router.push('/signup')
  }

