            {greeting && <p className="text-slate-400 text-sm">Hi, {greeting}</p>}
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => router.push('/post')}
              className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm fon{

